<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ABILITIES, ABILITY_NAME, SKILL_NAME, mod, signed, type Ability, type Skill } from '../rules/base'
import { RACES, BACKGROUNDS, race, background } from '../rules/races'
import { CLASSES, STYLES, classDef, type ClassId } from '../rules/classes'
import { defaultDraft, makeHero, problems, sheet, STANDARD, POINT_COST, availableSpells } from '../rules/hero'
import { spellsFor } from '../rules/spells'
import { item } from '../rules/items'
import { cryptoDie } from '../rules/base'
import { lookOf } from '../engine/compose'
import { keep } from '../heroes'
import { sfx } from '../audio'
import Bar from './Bar.vue'
import Looks from './Looks.vue'
import Stage3D from './Stage3D.vue'
const emit = defineEmits<{ done: [id: string] }>(); const d = reactive(defaultDraft('fighter', 'human')); const step = ref(0); const STEPS = ['Race', 'Class', 'Abilities', 'Background', 'Gear and magic', 'Looks and name']; const method = ref<'standard' | 'points' | 'roll'>('standard'), rolls = ref<number[]>([]); const st = ref<InstanceType<typeof Stage3D>>()
const R = computed(() => race(d.race)), C = computed(() => classDef(d.cls)); const hero = computed(() => { const h = makeHero({ ...d, name: d.name || 'x' }); return h }); const S = computed(() => sheet(hero.value)); const look = computed(() => ({ model: 'hero', hero: lookOf(hero.value) }))
const reset = () => { const n = defaultDraft(d.cls, d.race); d.base = n.base; d.pick = n.pick; d.skills = n.skills; d.expertise = []; d.style = n.style; d.kit = 0; d.cantrips = []; d.known = []; d.looks.cloth = n.looks.cloth; fixSkills() }
const setRace = (id: string) => { d.race = id; const r = race(id); if (!r.skins.includes(d.looks.skin)) d.looks.skin = r.skins[1] ?? r.skins[0]; if (r.hairs.length && !r.hairs.includes(d.looks.hair)) d.looks.hair = r.hairs[1] ?? r.hairs[0]; d.pick = r.pick ? (['dex', 'con', 'str', 'wis', 'int'] as Ability[]).filter(a => !r.bonus[a]).slice(0, r.pick) : []; fixSkills(); sfx.page() }, setCls = (id: ClassId) => { d.cls = id; reset(); sfx.page(); setTimeout(() => st.value?.play(C.value.caster?.kind === 'full' ? 'cast' : 'attack'), 500) }
const taken = computed(() => new Set<Skill>([...background(d.bg).skills, ...(R.value.skills ?? [])])); function fixSkills() { const from = C.value.skills.from.filter(s => !taken.value.has(s)); d.skills = d.skills.filter(s => from.includes(s)); for (const s of from) if (d.skills.length < C.value.skills.n && !d.skills.includes(s)) d.skills.push(s); d.skills = d.skills.slice(0, C.value.skills.n) }
watch(() => d.bg, fixSkills); const togSkill = (s: Skill) => { const i = d.skills.indexOf(s); if (i >= 0) d.skills.splice(i, 1); else { if (d.skills.length >= C.value.skills.n) d.skills.shift(); d.skills.push(s) } }
const spent = computed(() => ABILITIES.reduce((a, k) => a + (POINT_COST[d.base[k]] ?? 99), 0)); const setMethod = (m: typeof method.value) => { method.value = m; if (m === 'standard') C.value.array.forEach((a, i) => d.base[a] = STANDARD[i]); if (m === 'points') ABILITIES.forEach(a => d.base[a] = C.value.primary.includes(a) ? 15 : a === 'con' ? 14 : 8); if (m === 'points') while (spent.value < 27) { const a = C.value.array.find(x => d.base[x] < 15 && spent.value + POINT_COST[d.base[x] + 1] - POINT_COST[d.base[x]] <= 27); if (!a) break; d.base[a]++ } if (m === 'roll') rollAll() }
const rollAll = () => { sfx.dice(); rolls.value = ABILITIES.map(() => { const v = [1, 2, 3, 4].map(() => cryptoDie(6)).sort((a, b) => b - a); return v[0] + v[1] + v[2] }).sort((a, b) => b - a); C.value.array.forEach((a, i) => d.base[a] = rolls.value[i]) }
const pool = computed(() => method.value === 'roll' ? rolls.value : STANDARD); const swap = (a: Ability, v: number) => { const o = ABILITIES.find(k => k !== a && d.base[k] === v); if (o) d.base[o] = d.base[a]; d.base[a] = v }; const bump = (a: Ability, k: number) => { const v = d.base[a] + k; if (v < 8 || v > 15) return; const was = d.base[a]; d.base[a] = v; if (spent.value > 27) d.base[a] = was }
const togPick = (a: Ability) => { const i = d.pick.indexOf(a); if (i >= 0) d.pick.splice(i, 1); else { if (d.pick.length >= (R.value.pick ?? 0)) d.pick.shift(); d.pick.push(a) } }
const cantrips = computed(() => C.value.caster ? spellsFor(d.cls, 0) : []), firsts = computed(() => C.value.caster ? availableSpells(S.value).filter(s => s.lv === 1) : []); const knownN = computed(() => S.value.knownMax); const tog = (l: string[], id: string, n: number) => { const i = l.indexOf(id); if (i >= 0) l.splice(i, 1); else { if (l.length >= n) l.shift(); l.push(id) } }
const bad = computed(() => problems(d)); const name = () => { const l = R.value.names[d.looks.sex === 'f' ? 1 : 0]; d.name = l[Math.floor(Math.random() * l.length)] }
const done = () => { if (bad.value.length) return; const h = makeHero(d); keep(h); sfx.crit(); emit('done', h.id) }; const surprise = () => { d.looks.sex = Math.random() < .5 ? 'm' : 'f'; setRace(RACES[Math.floor(Math.random() * RACES.length)].id); setCls(CLASSES[Math.floor(Math.random() * CLASSES.length)].id); d.bg = BACKGROUNDS[Math.floor(Math.random() * BACKGROUNDS.length)].id; const pick = (l: string[]) => l[Math.floor(Math.random() * l.length)]; d.looks.skin = pick(R.value.skins); if (R.value.hairs.length) d.looks.hair = pick(R.value.hairs); d.looks.head = Math.floor(Math.random() * 5); d.looks.cloth = pick(DYES); d.looks.trim = pick(DYES); name(); step.value = 5 }
const DYES = ['#7a2a2a', '#8a5a2a', '#b08a3a', '#4a5a2a', '#2a5a4a', '#2a4a7a', '#3d5aa0', '#4a2a6a', '#7a2a5a', '#2a2a30', '#6a6a70', '#d8d0b8']
const frame = computed(() => step.value === 5 ? 'bust' as const : 'full' as const); const can = (i: number) => i <= 5
</script>
<template><main class="cr paper"><Bar title="Make a hero" @back="emit('done', '')"><nav><button v-for="(s, i) in STEPS" :key="s" :class="{ on: step === i, was: step > i }" :disabled="!can(i)" @click="step = i">{{ s }}</button></nav><button class="btn" @click="surprise">Surprise me</button></Bar>
  <div class="mid"><section class="show"><Stage3D ref="st" :look="look" :frame="frame" /><div class="plate"><b>{{ d.name || 'Unnamed' }}</b><span>{{ R.name }} {{ C.name.toLowerCase() }}</span><div class="nums"><span>{{ S.max }}<small>Hit points</small></span><span>{{ S.ac }}<small>Armour class</small></span><span>{{ S.speed }}<small>Speed</small></span><span>{{ signed(S.attacks[0].hit) }}<small>To hit</small></span></div></div></section>
  <section class="scroll page">
    <template v-if="step === 0"><h2>Where do you come from?</h2><div class="two"><div class="pick"><button v-for="r in RACES" :key="r.id" :class="{ on: d.race === r.id }" @click="setRace(r.id)"><b>{{ r.name }}</b><small>{{ Object.entries(r.bonus).length === 6 ? '+1 to all' : Object.entries(r.bonus).map(([k, v]) => `+${v} ${ABILITY_NAME[k as Ability].slice(0, 3)}`).join(', ') }}</small></button></div><div><h3>{{ R.name }}</h3><p class="aloud">{{ R.blurb }}</p><p class="muted">Speed {{ R.speed }} ft{{ R.dark ? `, darkvision ${R.dark} ft` : '' }}. Speaks {{ R.langs.join(', ') }}.</p><div v-for="t in R.traits" :key="t.id" class="ft"><b>{{ t.name }}.</b> {{ t.text }}</div><template v-if="R.pick"><span class="lab">Raise two more abilities by 1</span><div class="chips"><button v-for="a in ABILITIES.filter(x => !R.bonus[x])" :key="a" class="chip s" :class="{ on: d.pick.includes(a) }" @click="togPick(a)">{{ ABILITY_NAME[a] }}</button></div></template></div></div></template>
    <template v-if="step === 1"><h2>What do you do?</h2><div class="two"><div class="pick"><button v-for="c in CLASSES" :key="c.id" :class="{ on: d.cls === c.id }" @click="setCls(c.id)"><b>{{ c.name }}</b><small>d{{ c.hit }}, {{ c.primary.map(p => ABILITY_NAME[p]).join(', ') }}</small></button></div><div><h3>{{ C.name }}</h3><p class="aloud">{{ C.blurb }}</p><p class="muted">Armour: {{ C.armor.join(', ') || 'none' }}. Saves: {{ C.saves.map(s => ABILITY_NAME[s]).join(', ') }}.</p><div v-for="f in C.features.filter(f => f.lv <= 3 && !f.id.startsWith('asi'))" :key="f.id" class="ft"><small>Lv {{ f.lv }}</small> <b>{{ f.name }}.</b> {{ f.text }}</div><template v-if="C.style === 1"><span class="lab">Fighting style</span><div class="chips"><button v-for="s in STYLES" :key="s.id" class="chip s" :class="{ on: d.style === s.id }" v-tip="s.text" @click="d.style = s.id">{{ s.name }}</button></div></template></div></div></template>
    <template v-if="step === 2"><h2>What are you made of?</h2><div class="chips"><button v-for="m in ([['standard', 'Standard array'], ['points', 'Point buy'], ['roll', 'Roll 4d6']] as const)" :key="m[0]" class="chip" :class="{ on: method === m[0] }" @click="setMethod(m[0])">{{ m[1] }}</button><span v-if="method === 'points'" class="muted" style="align-self:center">{{ 27 - spent }} points left</span><button v-if="method === 'roll'" class="btn sm" @click="rollAll">Roll again</button></div>
      <div class="abs"><div v-for="a in ABILITIES" :key="a" class="ab" :class="{ key: C.primary.includes(a) }"><span class="k">{{ ABILITY_NAME[a] }}<small v-if="C.primary.includes(a)">key for a {{ C.name.toLowerCase() }}</small></span><template v-if="method === 'points'"><button class="ib sm" aria-label="Lower" @click="bump(a, -1)">−</button><b>{{ d.base[a] }}</b><button class="ib sm" aria-label="Raise" @click="bump(a, 1)">+</button></template><select v-else class="field" :value="d.base[a]" :aria-label="ABILITY_NAME[a]" @change="swap(a, +($event.target as HTMLSelectElement).value)"><option v-for="(v, i) in pool" :key="i" :value="v">{{ v }}</option></select><span class="race">{{ S.score[a] - d.base[a] ? `+${S.score[a] - d.base[a]} race` : '' }}</span><span class="tot">{{ S.score[a] }}</span><span class="md">{{ signed(mod(S.score[a])) }}</span></div></div></template>
    <template v-if="step === 3"><h2>Before all this?</h2><div class="two"><div class="pick"><button v-for="b in BACKGROUNDS" :key="b.id" :class="{ on: d.bg === b.id }" @click="d.bg = b.id"><b>{{ b.name }}</b><small>{{ b.skills.map(s => SKILL_NAME[s]).join(', ') }}</small></button></div><div><h3>{{ background(d.bg).name }}</h3><p class="aloud">{{ background(d.bg).feature }}</p><span class="lab">Choose {{ C.skills.n }} skills you trained as a {{ C.name.toLowerCase() }}</span><div class="chips"><button v-for="s in C.skills.from" :key="s" class="chip s" :class="{ on: d.skills.includes(s) || taken.has(s) }" :disabled="taken.has(s)" @click="togSkill(s)">{{ SKILL_NAME[s] }}</button></div><template v-if="d.cls === 'rogue'"><span class="lab">Expertise in two</span><div class="chips"><button v-for="s in d.skills" :key="s" class="chip s" :class="{ on: d.expertise.includes(s) }" @click="tog(d.expertise, s, 2)">{{ SKILL_NAME[s] }}</button></div></template><span class="lab">Your story, in a line or two (the Dungeon Master reads it)</span><textarea v-model="d.story" class="field" rows="3" maxlength="600" placeholder="Left the temple with someone else’s name." /></div></div></template>
    <template v-if="step === 4"><h2>What do you carry?</h2><div class="pick h"><button v-for="(k, i) in C.kits" :key="i" :class="{ on: d.kit === i }" @click="d.kit = i"><b>{{ k.name }}</b><small>{{ k.items.map(x => item(x).name).join(', ') }}</small></button></div><template v-if="C.caster"><div class="cap" style="margin-top:18px">Cantrips, {{ d.cantrips.length }} of {{ S.cantripMax }}</div><div class="sp"><button v-for="s in cantrips" :key="s.id" :class="{ on: d.cantrips.includes(s.id) }" @click="tog(d.cantrips, s.id, S.cantripMax)"><b>{{ s.name }}</b><small>{{ s.text }}</small></button></div><template v-if="knownN"><div class="cap" style="margin-top:18px">{{ d.cls === 'wizard' ? 'Spellbook' : 'Spells known' }}, {{ d.known.length }} of {{ knownN }}</div><div class="sp"><button v-for="s in firsts" :key="s.id" :class="{ on: d.known.includes(s.id) }" @click="tog(d.known, s.id, knownN)"><b>{{ s.name }}</b><small>{{ s.text }}</small></button></div></template><p v-else class="muted" style="margin-top:14px">You prepare {{ S.prepMax }} spells each day from the whole list. A sensible set is ready for you.</p><p class="muted tiny">Anything left unchosen is filled in for you.</p></template></template>
    <template v-if="step === 5"><h2>Who are you?</h2><div class="row" style="max-width:520px"><input v-model="d.name" class="field" maxlength="24" placeholder="Name" aria-label="Name" style="font:800 30px/1 var(--serif)"><button class="btn" @click="name">Suggest one</button></div><Looks :l="d.looks" :race="d.race" /></template>
  </section></div>
  <footer><span class="grow warn">{{ step === 5 ? bad[0] : '' }}</span><button class="btn" :disabled="!step" @click="step--">Back</button><button v-if="step < 5" class="btn primary big" @click="step++">{{ STEPS[step + 1] }}</button><button v-else class="btn primary big" :disabled="!!bad.length" @click="done">Sign the sheet</button></footer></main></template>
<style scoped>
.cr{position:fixed;inset:0;display:flex;flex-direction:column}nav{display:flex;flex-wrap:wrap}nav button{padding:6px 11px;color:var(--ink2);font-weight:500;border-bottom:4px solid transparent}nav .was{color:var(--ink)}nav .on{color:var(--ink);border-color:var(--spot)}
.mid{flex:1;min-height:0;display:grid;grid-template-columns:minmax(290px,32%) 1fr}.show{position:relative;background:var(--spot);min-height:0;display:flex;flex-direction:column}.show>:deep(canvas){flex:1;min-height:0}.plate{background:var(--paper);border-right:2px solid var(--ink);border-top:2px solid var(--ink);padding:12px 18px 14px}.plate b{display:block;font:800 34px/1 var(--serif)}.plate>span{font-size:17px;color:var(--ink2)}.nums{display:grid;grid-template-columns:repeat(4,1fr);border:2px solid var(--ink);margin-top:10px}.nums span{font:800 28px/1 var(--serif);text-align:center;padding:7px 0 5px;border-right:2px solid var(--ink)}.nums span:last-child{border:0}.nums small{display:block;font:400 13.5px/1.2 var(--ui);color:var(--ink2)}
.page{padding:26px clamp(18px,3vw,44px) 40px}.page h2{font:800 38px/1 var(--serif);margin-bottom:14px}.two{display:grid;grid-template-columns:minmax(200px,270px) 1fr;gap:34px;margin-top:18px}.pick{display:grid;align-content:start;border-top:2px solid var(--ink)}.pick button{display:block;padding:8px 11px 9px;border-bottom:1px solid var(--line2)}.pick.h{grid-template-columns:repeat(auto-fit,minmax(240px,1fr));border:0;gap:0 20px;margin-top:14px}.pick.h button{border-top:2px solid var(--ink)}.pick button:hover,.sp button:hover{background:var(--paper2)}.pick button.on,.sp button.on{background:var(--ink);color:var(--paper)}.pick .on small,.sp .on small{color:#c9ced4}.pick b,.sp b{font:700 20px/1.1 var(--serif);display:block}.pick small,.sp small{font-size:15px;line-height:1.25;color:var(--ink2);display:block}.ft{margin:0 0 8px;line-height:1.34;max-width:66ch}.ft small{font-size:15px;color:var(--ink2)}.aloud{max-width:60ch}
.abs{margin-top:18px;max-width:680px;border-top:3px solid var(--ink)}.ab{display:flex;align-items:center;gap:10px;padding:6px 0;border-bottom:1px solid var(--line2)}.ab .k{flex:1;font:700 21px/1 var(--serif)}.ab .k small{font:400 15px var(--ui);color:var(--ink2);margin-left:10px}.ab b{width:28px;text-align:center;font:700 20px var(--ui)}.ab .field{width:80px}.ab .ib{font-size:22px}.race{width:72px;font-size:15px;color:var(--ink2);text-align:right}.tot{width:40px;text-align:right;font:800 30px/1 var(--serif)}.md{width:54px;text-align:center;font:700 20px/34px var(--ui);background:var(--ink);color:var(--paper)}
.sp{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:0 20px}.sp button{display:block;padding:7px 9px;border-bottom:1px solid var(--line2)}
footer{display:flex;gap:8px;align-items:center;padding:10px clamp(14px,3vw,44px) calc(10px + var(--safe-b));border-top:5px solid var(--ink)}.warn{color:var(--bad);text-align:right}
@media(max-width:860px){.mid{grid-template-columns:1fr;grid-template-rows:30% 1fr}.show{flex-direction:row}.show>:deep(canvas){width:42%;flex:none;height:100%}.plate{flex:1;border:0;align-content:center;display:grid}.plate b{font-size:24px}.nums{grid-template-columns:1fr 1fr}.nums span{font-size:21px;border-bottom:1px solid var(--ink)}nav{flex-wrap:nowrap;overflow-x:auto;width:100%;order:9}.page{padding:16px}.page h2{font-size:30px}.two{grid-template-columns:1fr;gap:14px}.two .pick{grid-auto-flow:column;grid-auto-columns:max-content;grid-template-rows:repeat(3,auto);overflow-x:auto}}
</style>
